item.description:
## 九、插件开发

### 9.1 插件文件结构

```
my-plugin/
├── my-plugin.php                主插件文件（必须）
├── readme.txt                   插件说明（WordPress.org 要求）
├── uninstall.php                卸载脚本
├── includes/
│   ├── class-my-plugin.php      主类
│   ├── class-my-plugin-admin.php    后台类
│   └── class-my-plugin-frontend.php 前台类
├── admin/
│   ├── css/
│   ├── js/
│   └── views/
├── public/
│   ├── css/
│   ├── js/
│   └── views/
├── templates/
│   └── my-template.php
└── languages/
    └── my-plugin.pot
```

### 9.2 插件主文件

```php
<?php
/**
 * Plugin Name:       My Custom Plugin
 * Plugin URI:        https://example.com/my-plugin
 * Description:       A custom WordPress plugin for demonstration.
 * Version:           1.0.0
 * Requires at least: 6.0
 * Requires PHP:      7.4
 * Author:            Your Name
 * Author URI:        https://example.com
 * License:           GPL v2 or later
 * License URI:       https://www.gnu.org/licenses/gpl-2.0.html
 * Text Domain:       my-plugin
 * Domain Path:       /languages
 */

// 防止直接访问
if (!defined('ABSPATH')) {
    exit;
}

// 常量定义
define('MY_PLUGIN_VERSION', '1.0.0');
define('MY_PLUGIN_DIR', plugin_dir_path(__FILE__));
define('MY_PLUGIN_URL', plugin_dir_url(__FILE__));

// 激活钩子
register_activation_hook(__FILE__, 'my_plugin_activate');
function my_plugin_activate() {
    // 创建数据库表
    global $wpdb;
    $table_name = $wpdb->prefix . 'my_plugin_data';
    $charset_collate = $wpdb->get_charset_collate();

    $sql = 'CREATE TABLE $table_name (
        id mediumint(9) NOT NULL AUTO_INCREMENT,
        name varchar(100) NOT NULL,
        value text,
        created_at datetime DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (id)
    ) $charset_collate;';

    require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
    dbDelta($sql);

    // 设置默认选项
    add_option('my_plugin_settings', array(
        'enabled'      => true,
        'title'        => 'My Plugin',
        'items_per_page' => 10,
    ));

    // 设置默认选项
    flush_rewrite_rules();
}

// 停用钩子
register_deactivation_hook(__FILE__, 'my_plugin_deactivate');
function my_plugin_deactivate() {
    flush_rewrite_rules();
}

// 加载国际化
function my_plugin_load_textdomain() {
    load_plugin_textdomain('my-plugin', false, dirname(plugin_basename(__FILE__)) . '/languages');
}
add_action('init', 'my_plugin_load_textdomain');

// 加载后台脚本
function my_plugin_admin_scripts($hook) {
    if (strpos($hook, 'my-plugin') === false) {
        return;
    }

    wp_enqueue_style('my-plugin-admin', MY_PLUGIN_URL . 'admin/css/admin.css', array(), MY_PLUGIN_VERSION);
    wp_enqueue_script('my-plugin-admin', MY_PLUGIN_URL . 'admin/js/admin.js', array('jquery'), MY_PLUGIN_VERSION, true);

    wp_localize_script('my-plugin-admin', 'myPluginAdmin', array(
        'ajaxUrl' => admin_url('admin-ajax.php'),
        'nonce'   => wp_create_nonce('my_plugin_nonce'),
    ));
}
add_action('admin_enqueue_scripts', 'my_plugin_admin_scripts');

// 加载前台脚本
function my_plugin_frontend_scripts() {
    wp_enqueue_style('my-plugin-frontend', MY_PLUGIN_URL . 'public/css/frontend.css', array(), MY_PLUGIN_VERSION);
    wp_enqueue_script('my-plugin-frontend', MY_PLUGIN_URL . 'public/js/frontend.js', array(), MY_PLUGIN_VERSION, true);
}
add_action('wp_enqueue_scripts', 'my_plugin_frontend_scripts');
```

### 9.3 添加后台菜单页面

```php
<?php
// 添加顶级菜单
function my_plugin_menu() {
    add_menu_page(
        'My Plugin',                 // 页面标题
        'My Plugin',                 // 菜单标题
        'manage_options',            // 权限
        'my-plugin',                 // Slug
        'my_plugin_settings_page',   // 回调函数
        'dashicons-admin-plugins',   // 图标
        80                           // 位置
    );

    // 添加子菜单
    add_submenu_page(
        'my-plugin',
        'Settings',
        'Settings',
        'manage_options',
        'my-plugin-settings',
        'my_plugin_settings_page'
    );

    add_submenu_page(
        'my-plugin',
        'Data',
        'Data',
        'manage_options',
        'my-plugin-data',
        'my_plugin_data_page'
    );

    // 隐藏重复的子菜单（第一个子菜单 = 顶级菜单）
    global $submenu;
    unset($submenu['my-plugin'][0]);
}
add_action('admin_menu', 'my_plugin_menu');

// 设置页面内容
function my_plugin_settings_page() {
    ?>
    <div class='wrap'>
        <h1>My Plugin Settings</h1>
        <form method='post' action='options.php'>
            <?php
            settings_fields('my_plugin_settings_group');
            do_settings_sections('my-plugin-settings');
            submit_button();
            ?>
        </form>
    </div>
    <?php
}

// 注册设置
function my_plugin_register_settings() {
    register_setting('my_plugin_settings_group', 'my_plugin_settings', array(
        'sanitize_callback' => 'my_plugin_sanitize_settings',
    ));

    add_settings_section(
        'my_plugin_general_section',
        'General Settings',
        'my_plugin_section_callback',
        'my-plugin-settings'
    );

    add_settings_field(
        'my_plugin_enabled',
        'Enable Plugin',
        'my_plugin_enabled_callback',
        'my-plugin-settings',
        'my_plugin_general_section'
    );

    add_settings_field(
        'my_plugin_title',
        'Plugin Title',
        'my_plugin_title_callback',
        'my-plugin-settings',
        'my_plugin_general_section'
    );
}
add_action('admin_init', 'my_plugin_register_settings');

// 字段回调
function my_plugin_enabled_callback() {
    $options = get_option('my_plugin_settings');
    ?>
    <input type='checkbox' name='my_plugin_settings[enabled]' value='1' <?php checked(1, $options['enabled'] ?? 0); ?>>
    <?php
}

function my_plugin_title_callback() {
    $options = get_option('my_plugin_settings');
    ?>
    <input type='text' name='my_plugin_settings[title]' value='<?php echo esc_attr($options['title'] ?? ''); ?>' class='regular-text'>
    <?php
}

// 清理回调
function my_plugin_sanitize_settings($input) {
    $sanitized = array();
    $sanitized['enabled'] = !empty($input['enabled']) ? 1 : 0;
    $sanitized['title'] = sanitize_text_field($input['title'] ?? '');
    return $sanitized;
}
```

### 9.4 AJAX 处理

```php
<?php
// AJAX 处理（登录用户）
function my_plugin_ajax_handler() {
    // 验证 nonce
    if (!wp_verify_nonce($_POST['nonce'] ?? '', 'my_plugin_nonce')) {
        wp_send_json_error('Security check failed');
    }

    // 验证权限
    if (!current_user_can('manage_options')) {
        wp_send_json_error('Permission denied');
    }

    $action_type = sanitize_text_field($_POST['action_type'] ?? '');

    switch ($action_type) {
        case 'save_data':
            $name = sanitize_text_field($_POST['name'] ?? '');
            $value = sanitize_textarea_field($_POST['value'] ?? '');

            global $wpdb;
            $result = $wpdb->insert($wpdb->prefix . 'my_plugin_data', array(
                'name'  => $name,
                'value' => $value,
            ));

            if ($result) {
                wp_send_json_success(array('message' => 'Data saved successfully'));
            } else {
                wp_send_json_error('Failed to save data');
            }
            break;

        case 'get_data':
            global $wpdb;
            $data = $wpdb->get_results('SELECT * FROM {$wpdb->prefix}my_plugin_data ORDER BY created_at DESC LIMIT 10');
            wp_send_json_success($data);
            break;

        default:
            wp_send_json_error('Unknown action');
    }
}
add_action('wp_ajax_my_plugin_action', 'my_plugin_ajax_handler');

// AJAX 处理（未登录用户）
// add_action('wp_ajax_nopriv_my_plugin_action', 'my_plugin_ajax_handler');
```

**前端 AJAX 调用（JavaScript）：**
```javascript
jQuery(document).ready(function($) {
    // 保存数据
    $.ajax({
        url: myPluginAdmin.ajaxUrl,
        type: 'POST',
        data: {
            action: 'my_plugin_action',
            nonce: myPluginAdmin.nonce,
            action_type: 'save_data',
            name: 'test',
            value: 'test value'
        },
        success: function(response) {
            if (response.success) {
                console.log(response.data.message);
            }
        }
    });
});
```

---

## 十、WordPress 钩子系统

### 10.1 Action（动作钩子）

```php
// 添加动作
add_action('hook_name', 'callback_function', $priority, $accepted_args);

// 示例：在页面底部添加内容
function my_custom_footer_content() {
    echo '<p>Powered by My Theme</p>';
}
add_action('wp_footer', 'my_custom_footer_content');

// 常用 Action 钩子
// init                  WordPress 初始化后（加载主题/插件后）
// wp_loaded             所有内容加载完成后
// template_redirect     模板加载前
// wp_head               <head> 标签内
// wp_footer             </body> 标签前
// wp_body_open          <body> 标签打开后
// after_setup_theme     主题设置后
// wp_enqueue_scripts    前台脚本加载
// admin_enqueue_scripts 后台脚本加载
// save_post             保存文章后
// publish_post          发布文章后
// delete_post           删除文章后
// user_register         用户注册后
// wp_login              用户登录后
// wp_logout             用户登出后
// comment_post          发表评论后
// switch_theme          切换主题后
// admin_menu            添加后台菜单
// widgets_init          注册小工具
```

### 10.2 Filter（过滤器钩子）

```php
// 添加过滤器
add_filter('hook_name', 'callback_function', $priority, $accepted_args);

// 示例：修改文章标题
function my_custom_title($title) {
    if (is_single()) {
        $title = $title . ' - My Blog';
    }
    return $title;
}
add_filter('the_title', 'my_custom_title');

// 示例：修改摘要长度
function my_excerpt_length($length) {
    return 50;
}
add_filter('excerpt_length', 'my_excerpt_length', 999);

// 常用 Filter 钩子
// the_title             文章标题
// the_content           文章内容
// the_excerpt           文章摘要
// excerpt_length        摘要长度
// excerpt_more          摘要后缀
// wp_title              页面标题
// body_class            body 类名
// post_class            文章类名
// upload_mimes          允许上传的文件类型
// login_redirect        登录后跳转
// wp_mail_from          邮件发送者
// wp_mail_from_name     邮件发送者名称
// comment_text          评论内容
// wp_nav_menu_items     菜单项 HTML
// widget_display_callback 小工具显示
// the_editor            编辑器内容
// query_vars            查询变量
// cron_schedules        自定义 cron 间隔
```

### 10.3 自定义钩子

```php
// 自定义 Action
do_action('my_custom_action', $arg1, $arg2);

// 其他代码中使用
add_action('my_custom_action', 'my_callback_function', 10, 2);
function my_callback_function($arg1, $arg2) {
    // 处理逻辑
}

// 自定义 Filter
$value = apply_filters('my_custom_filter', $original_value, $arg1);

// 其他代码中使用
add_filter('my_custom_filter', 'my_filter_function', 10, 2);
function my_filter_function($value, $arg1) {
    return $value . ' modified';
}
```

