### 18.2 核心命令

```bash
# WordPress 核心
wp core download                          # 下载 WordPress
wp core install                           # 安装 WordPress
wp core update                            # 更新 WordPress
wp core version                           # 查看版本

# 安装 WordPress
wp core install --url='https://example.com' \
    --title='My Site' \
    --admin_user='admin' \
    --admin_password='StrongPass123!' \
    --admin_email='admin@example.com' \
    --locale='zh_CN' \
    --skip-email

# 数据库
wp db create                              # 创建数据库
wp db export backup.sql                   # 导出数据库
