wp search-replace 'old.com' 'new.com'     # 批量替换

# 文章
wp post list                              # 列出文章
wp post create --post_title='Hello' --post_content='World' --post_status=publish
wp post update 1 --post_title='New Title'
wp post delete 1 --force
