## 二十、完整实战示例

### 20.1 一键部署脚本

```bash
#!/bin/bash
# deploy_wordpress.sh
set -e

DOMAIN='example.com'
DB_NAME='wordpress'
DB_USER='wpuser'
DB_PASS=$(openssl rand -base64 24)
WP_DIR='/var/www/wordpress'
ADMIN_USER='admin'
ADMIN_PASS=$(openssl rand -base64 16)
ADMIN_EMAIL='admin@example.com'

echo '=== WordPress 一键部署 ==='

# 1. 安装 LAMP/LNMP
echo '[1/7] 安装环境...'
apt update && apt install -y nginx php-fpm php-mysql php-curl php-gd php-mbstring php-xml php-zip php-intl mysql-server certbot python3-certbot-nginx

# 2. 创建数据库
echo '[2/7] 创建数据库...'
mysql -u root -p -e '
CREATE DATABASE IF NOT EXISTS $DB_NAME DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS '$DB_USER'@'localhost' IDENTIFIED BY '$DB_PASS';
GRANT ALL PRIVILEGES ON $DB_NAME.* TO '$DB_USER'@'localhost';
FLUSH PRIVILEGES;
'

# 3. 下载 WordPress
echo '[3/7] 下载 WordPress...'
cd /var/www
wget -q https://wordpress.org/latest.tar.gz
tar -xzf latest.tar.gz
chown -R www-data:www-data $WP_DIR

# 4. 配置 wp-config.php
echo '[4/7] 配置 WordPress...'
cd $WP_DIR
cp wp-config-sample.php wp-config.php

# 生成密钥
SALTS=$(curl -s https://api.wordpress.org/secret-key/1.1/salt/)

cat > wp-config.php << EOF
<?php
define('DB_NAME', '$DB_NAME');
define('DB_USER', '$DB_USER');
define('DB_PASSWORD', '$DB_PASS');
define('DB_HOST', 'localhost');
define('DB_CHARSET', 'utf8mb4');
define('DB_COLLATE', 'utf8mb4_unicode_ci');

$SALTS

\$table_prefix = 'wp_';
define('WP_DEBUG', false);
define('WP_MEMORY_LIMIT', '256M');
define('DISALLOW_FILE_EDIT', true);
define('WP_AUTO_UPDATE_CORE', 'minor');
define('FS_METHOD', 'direct');

if ( ! defined( 'ABSPATH' ) ) {
    define( 'ABSPATH', __DIR__ . '/' );
}
require_once ABSPATH . 'wp-settings.php';
EOF

# 5. 配置 Nginx
echo '[5/7] 配置 Nginx...'
cat > /etc/nginx/sites-available/wordpress << EOF
server {
    listen 80;
    server_name $DOMAIN www.$DOMAIN;
    root $WP_DIR;
    index index.php;

    client_max_body_size 64M;

    location / {
        try_files \$uri \$uri/ /index.php?\$args;
    }

    location ~ \.php\$ {
        fastcgi_pass unix:/run/php/php8.1-fpm.sock;
        fastcgi_param SCRIPT_FILENAME \$document_root\$fastcgi_script_name;
        include fastcgi_params;
        fastcgi_read_timeout 300;
    }

    location ~* /\.ht { deny all; }
    location = /wp-config.php { deny all; }
    location = /xmlrpc.php { deny all; }

    location ~* \.(jpg|jpeg|png|gif|ico|css|js|woff2|svg)\$ {
        expires 30d;
        access_log off;
    }
}
EOF

ln -sf /etc/nginx/sites-available/wordpress /etc/nginx/sites-enabled/
nginx -t && systemctl reload nginx

# 6. 安装 WordPress
echo '[6/7] 安装 WordPress...'
cd $WP_DIR
wp core install \
    --url='http://$DOMAIN' \
    --title='$DOMAIN' \
    --admin_user='$ADMIN_USER' \
    --admin_password='$ADMIN_PASS' \
    --admin_email='$ADMIN_EMAIL' \
    --locale='zh_CN' \
    --skip-email \
    --allow-root

# 7. 基本配置
echo '[7/7] 基本配置...'
wp option update permalink_structure '/%postname%/' --allow-root
wp rewrite flush --allow-root
wp plugin install akismet --activate --allow-root
wp plugin install wordpress-seo --activate --allow-root
wp theme install generatepress --activate --allow-root

echo ''
echo '=== 部署完成 ==='
echo '站点地址: http://$DOMAIN'
echo '后台地址: http://$DOMAIN/wp-admin'
echo '管理员:   $ADMIN_USER'
echo '密码:     $ADMIN_PASS'
echo '数据库:   $DB_NAME'
echo 'DB 用户:  $DB_USER'
echo 'DB 密码:  $DB_PASS'
echo ''
echo '请立即登录后台并修改密码！'
echo '下一步：配置 SSL（sudo certbot --nginx -d $DOMAIN）'
```

### 20.2 自定义短代码插件

```php
<?php
/**
 * Plugin Name: My Shortcodes
 * Description: 自定义短代码集合
 * Version: 1.0.0
 * Author: Your Name
 * Text Domain: my-shortcodes
 */

if (!defined('ABSPATH')) exit;

// 按钮短代码 [my_button url='#' text='点击这里' color='blue' size='large']
function my_button_shortcode($atts) {
    $atts = shortcode_atts(array(
        'url'   => '#',
        'text'  => 'Click Here',
        'color' => 'blue',
        'size'  => 'medium',
        'target' => '_self',
    ), $atts, 'my_button');

    return sprintf(
        '<a href='%s' class='my-btn my-btn-%s my-btn-%s' target='%s'>%s</a>',
        esc_url($atts['url']),
        esc_attr($atts['color']),
        esc_attr($atts['size']),
        esc_attr($atts['target']),
        esc_html($atts['text'])
    );
}
add_shortcode('my_button', 'my_button_shortcode');

// 信息框短代码 [my_alert type='info' title='提示']内容[/my_alert]
function my_alert_shortcode($atts, $content = null) {
    $atts = shortcode_atts(array(
        'type'  => 'info',
        'title' => '',
    ), $atts, 'my_alert');

    $types = array('info', 'success', 'warning', 'error');
    $type = in_array($atts['type'], $types) ? $atts['type'] : 'info';

    $html = '<div class='my-alert my-alert-' . esc_attr($type) . ''>';
    if (!empty($atts['title'])) {
        $html .= '<strong>' . esc_html($atts['title']) . '</strong>';
    }
    $html .= '<p>' . wp_kses_post(do_shortcode($content)) . '</p>';
    $html .= '</div>';

    return $html;
}
add_shortcode('my_alert', 'my_alert_shortcode');

// 文章列表短代码 [my_posts category='news' count='5' layout='grid']
function my_posts_shortcode($atts) {
    $atts = shortcode_atts(array(
        'category' => '',
        'count'    => 5,
        'layout'   => 'list',
    ), $atts, 'my_posts');

    $args = array(
        'post_type'      => 'post',
        'posts_per_page' => intval($atts['count']),
        'orderby'        => 'date',
        'order'          => 'DESC',
    );

    if (!empty($atts['category'])) {
        $args['category_name'] = sanitize_text_field($atts['category']);
    }

    $query = new WP_Query($args);
    $html = '<div class='my-posts my-posts-' . esc_attr($atts['layout']) . ''>';

    if ($query->have_posts()) {
        while ($query->have_posts()) {
            $query->the_post();
            $html .= '<div class='my-post-item'>';
            $html .= '<h3><a href='' . get_permalink() . ''>' . get_the_title() . '</a></h3>';
            $html .= '<p>' . get_the_excerpt() . '</p>';
            $html .= '<span class='date'>' . get_the_date() . '</span>';
            $html .= '</div>';
        }
    } else {
        $html .= '<p>暂无文章</p>';
    }

    $html .= '</div>';
    wp_reset_postdata();

    return $html;
}
add_shortcode('my_posts', 'my_posts_shortcode');

// 加载短代码样式
function my_shortcodes_styles() {
    wp_enqueue_style('my-shortcodes', plugin_dir_url(__FILE__) . 'assets/css/shortcodes.css', array(), '1.0.0');
}
add_action('wp_enqueue_scripts', 'my_shortcodes_styles');
```

### 20.3 自定义文章类型插件

```php
<?php
/**
 * Plugin Name: My Custom Post Types
 * Description: 注册自定义文章类型和分类法
 * Version: 1.0.0
 */

if (!defined('ABSPATH')) exit;

// 注册自定义文章类型
function my_register_post_types() {

    // 作品集（Portfolio）
    register_post_type('portfolio', array(
        'labels' => array(
            'name'               => '作品集',
            'singular_name'      => '作品',
            'add_new'            => '添加作品',
            'add_new_item'       => '添加新作品',
            'edit_item'          => '编辑作品',
            'new_item'           => '新作品',
            'view_item'          => '查看作品',
            'search_items'       => '搜索作品',
            'not_found'          => '未找到作品',
            'not_found_in_trash' => '回收站中无作品',
        ),
        'public'          => true,
        'has_archive'     => true,
        'rewrite'         => array('slug' => 'portfolio'),
        'menu_icon'       => 'dashicons-portfolio',
        'supports'        => array('title', 'editor', 'thumbnail', 'excerpt', 'custom-fields', 'comments'),
        'show_in_rest'    => true,
        'capability_type' => 'post',
    ));

    // 产品（Product）
    register_post_type('product', array(
        'labels' => array(
            'name'          => '产品',
            'singular_name' => '产品',
            'add_new'       => '添加产品',
            'edit_item'     => '编辑产品',
        ),
        'public'       => true,
        'has_archive'  => true,
        'rewrite'      => array('slug' => 'product'),
        'menu_icon'    => 'dashicons-cart',
        'supports'     => array('title', 'editor', 'thumbnail', 'excerpt', 'custom-fields'),
        'show_in_rest' => true,
    ));
}
add_action('init', 'my_register_post_types');

// 注册自定义分类法
function my_register_taxonomies() {

    // 作品分类
    register_taxonomy('portfolio_category', 'portfolio', array(
        'labels' => array(
            'name'          => '作品分类',
            'singular_name' => '作品分类',
            'add_new_item'  => '添加作品分类',
        ),
        'hierarchical'      => true,
        'rewrite'           => array('slug' => 'portfolio-category'),
        'show_admin_column' => true,
        'show_in_rest'      => true,
    ));

    // 产品标签
    register_taxonomy('product_tag', 'product', array(
        'labels' => array(
            'name'          => '产品标签',
            'singular_name' => '产品标签',
        ),
        'hierarchical'      => false,
        'rewrite'           => array('slug' => 'product-tag'),
        'show_admin_column' => true,
        'show_in_rest'      => true,
    ));
}
add_action('init', 'my_register_taxonomies');

// 注册自定义元数据
function my_register_meta() {
    register_post_meta('portfolio', 'project_url', array(
        'show_in_rest'  => true,
        'single'        => true,
        'type'          => 'string',
        'auth_callback' => function() { return current_user_can('edit_posts'); },
    ));

    register_post_meta('portfolio', 'client_name', array(
        'show_in_rest'  => true,
        'single'        => true,
        'type'          => 'string',
        'auth_callback' => function() { return current_user_can('edit_posts'); },
    ));

    register_post_meta('product', 'price', array(
        'show_in_rest'  => true,
        'single'        => true,
        'type'          => 'string',
        'auth_callback' => function() { return current_user_can('edit_posts'); },
    ));

    register_post_meta('product', 'sku', array(
        'show_in_rest'  => true,
        'single'        => true,
        'type'          => 'string',
        'auth_callback' => function() { return current_user_can('edit_posts'); },
    ));
}
add_action('init', 'my_register_meta');
```

